    if (local != null) {
      cb.onDataFetcherReady(sourceKey, data, local.fetcher, DataSource.DATA_DISK_CACHE, sourceKey);
    }/' library/src/main/java/com/bumptech/glide/load/engine/DataCacheGenerator.java && sed -i '108,111s/cb.onDataFetcherFailed(sourceKey, e, loadData.fetcher, DataSource.DATA_DISK_CACHE);/LoadData<?> local = loadData;
